// Strategy 1: Improving Spatial Locality (Stride-1 Access)
#define N 1024
int matrix[N][N]; // C/C++ is Row-Major

// GOOD: Inner loop traverses rows contiguously (i.e., [i][j], [i][j+1])
void row_major_access() {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            matrix[i][j] = i + j;
}

// BAD: Inner loop forces cache line evictions quickly (Stride = N)
void column_major_access() {
    for (int j = 0; j < N; ++j)
        for (int i = 0; i < N; ++i)
            matrix[i][j] = i + j;
}

// Strategy 2: Cache Blocking/Tiling (Minimizing Capacity/Conflict Misses)
#define BLOCK_SIZE 64
void tiled_processing() {
    for (int bi = 0; bi < N; bi += BLOCK_SIZE)
        for (int bj = 0; bj < N; bj += BLOCK_SIZE)
            // Process the current block
            for (int i = bi; i < bi + BLOCK_SIZE; ++i)
                for (int j = bj; j < bj + BLOCK_SIZE; ++j)
                    matrix[i][j] *= 2;
}
